840						e.AssetID, e.TicketID)
841				}
842				derivedTicket[e.TicketID] = ticketOpen
843				derivedOpen[e.AssetID] = e.TicketID
844			case eventDeactivate:
845				// 停用要求当时“可用”（无未关闭工单且未停用）；维修中（有未关闭
846				// 工单）的资产不能停用。From/To 须与实际转换一致。
847				if derivedOpen[e.AssetID] != "" {
848					return fmt.Errorf("履历矛盾：资产 %s 在存在未关闭工单时出现停用履历（序号 %d）",
849						e.AssetID, e.Seq)
850				}
851				if derivedDeactivated[e.AssetID] {
852					return fmt.Errorf("履历矛盾：资产 %s 被重复停用（序号 %d）", e.AssetID, e.Seq)
853				}
854				if e.From != statusAvailable || e.To != statusDeactivated {
855					return fmt.Errorf("履历矛盾：停用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
856						e.Seq, statusAvailable, statusDeactivated, e.From, e.To)
857				}
858				derivedDeactivated[e.AssetID] = true
859			case eventReactivate:
860				// 恢复使用只作用于停用资产；From/To 须与实际转换一致。
861				if !derivedDeactivated[e.AssetID] {
862					return fmt.Errorf("履历矛盾：资产 %s 未停用却出现恢复使用履历（序号 %d）", e.AssetID, e.Seq)
863				}
864				if derivedOpen[e.AssetID] != "" {
865					return fmt.Errorf("履历矛盾：资产 %s 恢复使用（序号 %d）时仍存在未关闭工单",
866						e.AssetID, e.Seq)
867				}
868				if e.From != statusDeactivated || e.To != statusAvailable {
869					return fmt.Errorf("履历矛盾：恢复使用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
870						e.Seq, statusDeactivated, statusAvailable, e.From, e.To)
871				}
872				delete(derivedDeactivated, e.AssetID)
873			case eventAssign:
874				if derivedTicket[e.TicketID] != ticketOpen {
875					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
876				}
877				if e.From != derivedAssignee[e.TicketID] {
878					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
879						e.TicketID, e.Seq, e.From)
880				}
881				derivedAssignee[e.TicketID] = e.To
882				derivedNote[e.TicketID] = e.Content
883			case eventClose:
884				if derivedTicket[e.TicketID] != ticketOpen {
885					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
886				}
887				derivedTicket[e.TicketID] = ticketClosed
888				delete(derivedOpen, e.AssetID)
889			case eventCancel:
890				if derivedTicket[e.TicketID] != ticketOpen {
891					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
892				}
893				derivedTicket[e.TicketID] = ticketCancelled
894				delete(derivedOpen, e.AssetID)
895			case eventPartWithdraw:
896				// 领用须在报修之后、终结之前；履历与领用记录的业务字段必须一致。
897				if derivedTicket[e.TicketID] != ticketOpen {
898					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现领用履历（序号 %d）",
899						e.TicketID, e.Seq)
900				}
901				p := parts[e.WithdrawalID]
902				if p == nil {
903					return fmt.Errorf("履历矛盾：领用履历（序号 %d）引用了不存在的领用记录 %s",
904						e.Seq, e.WithdrawalID)
905				}
906				if withdrawSeq[p.ID] != 0 {
907					return fmt.Errorf("履历矛盾：领用记录 %s 有多条领用履历", p.ID)
908				}
909				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID ||
910					p.Quantity != e.Quantity || p.Note != e.Content {
911					return fmt.Errorf("履历矛盾：领用履历（序号 %d）与领用记录 %s 的工单、资产、备件、数量或说明不一致",
912						e.Seq, p.ID)
913				}
914				withdrawSeq[p.ID] = e.Seq
915			case eventPartReturn:
916				// 退回须在报修之后、终结之前，且指向先前已领用的记录；
917				// 累计退回不得超过该笔原数量。
918				if derivedTicket[e.TicketID] != ticketOpen {
919					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现退回履历（序号 %d）",
920						e.TicketID, e.Seq)
921				}
922				p := parts[e.WithdrawalID]
923				if p == nil {
924					return fmt.Errorf("履历矛盾：退回履历（序号 %d）引用了不存在的领用记录 %s",
925						e.Seq, e.WithdrawalID)
926				}
927				if withdrawSeq[p.ID] == 0 {
928					return fmt.Errorf("履历矛盾：退回履历（序号 %d）出现在领用记录 %s 的领用履历之前",
929						e.Seq, p.ID)
930				}
931				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID {
932					return fmt.Errorf("履历矛盾：退回履历（序号 %d）与领用记录 %s 的工单、资产或备件不一致",
933						e.Seq, p.ID)
934				}
935				// 逐步核对累计退回不超过原数量：先做不会溢出的减法比较再累加。
936				// 直接相加可能整数溢出回绕，即使回绕后的累计恰好等于保存值，
937				// 实际超额的履历也必须拒绝。
938				if e.Quantity > p.Quantity-derivedReturned[p.ID] {
939					return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回在履历序号 %d 处超过原数量 %d",
940						p.ID, e.Seq, p.Quantity)
941				}
942				derivedReturned[p.ID] += e.Quantity
943			case eventAttach:
944				// 登记须在报修之后；未关闭、已关闭或已取消工单均可补充资料。
945				// 履历与附件记录的业务字段必须一致。
946				if derivedTicket[e.TicketID] == "" {
947					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件登记履历（序号 %d）",
948						e.TicketID, e.Seq)
949				}
950				a := attachments[e.AttachmentID]
951				if a == nil {
952					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）引用了不存在的附件记录 %s",
953						e.Seq, e.AttachmentID)
954				}
955				if attachRegSeq[a.ID] != 0 {
956					return fmt.Errorf("履历矛盾：附件记录 %s 有多条登记履历", a.ID)
957				}
958				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.Note != e.Content {
959					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）与附件记录 %s 的工单、资产、路径或说明不一致",
960						e.Seq, a.ID)
961				}
962				attachRegSeq[a.ID] = e.Seq
963			case eventAttachRevoke:
964				// 撤销须在登记之后，且每个附件至多撤销一次；
965				// 履历与附件记录的业务字段必须一致。
966				if derivedTicket[e.TicketID] == "" {
967					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件撤销履历（序号 %d）",
968						e.TicketID, e.Seq)
969				}
970				a := attachments[e.AttachmentID]
971				if a == nil {
972					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）引用了不存在的附件记录 %s",
973						e.Seq, e.AttachmentID)
974				}
975				if attachRegSeq[a.ID] == 0 {
976					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）出现在附件记录 %s 的登记履历之前",
977						e.Seq, a.ID)
978				}
979				if attachRevokeSeq[a.ID] != 0 {
980					return fmt.Errorf("履历矛盾：附件记录 %s 有多条撤销履历", a.ID)
981				}
982				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.RevokeReason != e.Content {
983					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）与附件记录 %s 的工单、资产、路径或撤销理由不一致",
984						e.Seq, a.ID)
985				}
986				attachRevokeSeq[a.ID] = e.Seq
987			}
988		}
989		for _, t := range d.Tickets {
990			if derivedTicket[t.ID] != t.Status {
991				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
992					t.ID, derivedTicket[t.ID], t.Status)
993			}
994			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
995			if derivedAssignee[t.ID] != t.Assignee {
996				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
997					t.ID, derivedAssignee[t.ID], t.Assignee)
998			}
999			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
1000				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
1001			}
1002		}
1003		// 每笔领用记录恰有一条领用履历；按履历重放得到的累计退回须与保存值一致。
1004		for _, p := range d.Parts {
1005			if withdrawSeq[p.ID] == 0 {
1006				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
1007			}
1008			if derivedReturned[p.ID] != p.Returned {
1009				return fmt.Errorf("备件数量矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
1010					p.ID, derivedReturned[p.ID], p.Returned)
1011			}
1012		}
1013		// 每条附件记录恰有一条登记履历、至多一条撤销履历；记录的撤销状态须与
1014		// 是否存在撤销履历一致。
1015		for _, a := range d.Attachments {
1016			if attachRegSeq[a.ID] == 0 {
1017				return fmt.Errorf("履历矛盾：附件记录 %s 缺少对应的登记履历", a.ID)
1018			}
1019			if revoked := attachRevokeSeq[a.ID] != 0; revoked != a.Revoked {
1020				return fmt.Errorf("状态矛盾：附件记录 %s 保存的撤销状态与履历不符", a.ID)
1021			}
1022		}
1023		for _, a := range d.Assets {
1024			want := statusAvailable
1025			switch {
1026			case derivedDeactivated[a.ID]:
1027				want = statusDeactivated
1028			case derivedOpen[a.ID] != "":
1029				want = statusRepairing
1030			}
1031			if a.Status != want {
1032				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
1033					a.ID, want, a.Status)
1034			}
1035		}
