1037		plans := map[string]*Plan{}
1038		for _, p := range d.Plans {
1039			if p == nil || p.AssetID == "" || p.Content == "" {
1040				return errors.New("数据矛盾：存在字段不完整的保养计划")
1041			}
1042			if assets[p.AssetID] == nil {
1043				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
1044			}
1045			if plans[p.AssetID] != nil {
1046				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
1047			}
1048			if _, err := parseDate(p.FirstDue); err != nil {
1049				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
1050			}
1051			if p.IntervalDays < 1 {
1052				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
1053			}
1054			if _, err := parseDate(p.NextDue); err != nil {
1055				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
1056			}
1057			plans[p.AssetID] = p
1058		}
1059		// 保养履历链：每个计划恰有一条建立履历；建立与每次调整以各自的全库履历序号
1060		// 划分方案段（不按日期或数组位置），当前段方案为最近一次建立或调整记录的
1061		// 内容、首次到期日与间隔。完成履历按序号接续（周期到期日须等于当时下一
1062		// 到期日，完成日不早于它，按当时所在段的首次日加整数倍间隔推进），撤销履历
1063		// 须引用当时所在段内未撤销且最新有效的完成，并把下一到期日恢复为该完成的
1064		// 周期到期日；调整履历记录的原方案与原下一到期日须与当时状态一致，新首次
1065		// 到期日须严格晚于当时所有未撤销完成的实际完成日，调整后下一到期日即新
1066		// 首次到期日，旧段完成不能再撤销。由履历推出的当前方案与下一到期日须与
1067		// 计划保存的一致。没有计划的资产不得有保养履历。停用状态随全库履历序号
1068		// 推进：停用期间不得登记保养完成；停用不暂停、不重算周期，因此建立、完成、
1069		// 撤销与调整的接续规则本身不受影响。以上判定与状态推进全部由保养规则核心
1070		// （maintcore.go）完成，与日常操作共用同一套规则；核心只读履历，不修改
1071		// 任何业务记录，也不补字段或修复数据。
1072		core := newMaintCore()
1073		for _, e := range sorted {
1074			if isPlanEvent(e.Kind) && plans[e.AssetID] == nil {
1075				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
1076			}
1077			if err := core.apply(e); err != nil {
1078				return maintValidateError(err)
1079			}
1080		}
1081		for _, p := range d.Plans {
1082			content, firstDue, interval, nextDue, created := core.derived(p.AssetID)
1083			if !created {
1084				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
1085			}
1086			if content != p.Content || firstDue != p.FirstDue || interval != p.IntervalDays {
1087				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的当前方案（内容 %q、首次到期日 %s、每 %d 天）与保存的方案（内容 %q、首次到期日 %s、每 %d 天）不符",
1088					p.AssetID, content, firstDue, interval,
1089					p.Content, p.FirstDue, p.IntervalDays)
1090			}
1091			if nextDue != p.NextDue {
1092				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
1093					p.AssetID, nextDue, p.NextDue)
1094			}
1095		}
1096		return nil
1097	}
