1099	// maintValidateError 把保养规则核心返回的规则冲突包装为台账校验场景的错误
1100	// （指明“履历矛盾”类别）；调用方拒绝查询与写入并保留原文件。
1101	func maintValidateError(err error) error {
1102		var re *maintRuleError
1103		if !errors.As(err, &re) {
1104			return err
1105		}
1106		switch re.code {
1107		case ruleDuplicateCreate:
1108			return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", re.assetID)
1109		case ruleBeforeCreate:
1110			return fmt.Errorf("履历矛盾：资产 %s 的%s履历（序号 %d）出现在建立履历之前",
1111				re.assetID, re.kind, re.seq)
1112		case ruleAdjustScheme:
1113			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原方案与资产 %s 当时的方案不符",
1114				re.seq, re.assetID)
1115		case ruleAdjustNextDue:
1116			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原下一到期日 %s 与当时的下一到期日 %s 不符",
1117				re.seq, re.dateA, re.dateB)
1118		case ruleAdjustFirstDue:
1119			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）的新首次到期日 %s 未严格晚于未撤销完成（序号 %d）的实际完成日 %s",
1120				re.seq, re.dateA, re.doneSeq, re.dateB)
1121		case ruleRevokeOldSegment:
1122			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销",
1123				re.seq, re.target, re.assetID)
1124		case ruleRevokeUnknown:
1125			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历",
1126				re.seq, re.target, re.assetID)
1127		case ruleRevokeDuplicate:
1128			return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", re.target, re.seq)
1129		case ruleRevokeNotLatest:
1130			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）",
1131				re.seq, re.target, re.latest)
1132		case ruleDoneDeactivated:
1133			return fmt.Errorf("履历矛盾：资产 %s 在停用期间出现保养完成履历（序号 %d）", re.assetID, re.seq)
1134		case ruleDueMismatch:
1135			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
1136				re.assetID, re.seq, re.dateA, re.dateB)
1137		case ruleDoneBeforeDue:
1138			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）完成日 %s 早于周期到期日 %s",
1139				re.assetID, re.seq, re.dateA, re.dateB)
1140		case ruleNextOverflow:
1141			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
1142				re.assetID, re.seq)
1143		}
1144		return err
1145	}
1146	
1147	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1148	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1149	// 保持不变，不留下部分业务变化。
1150	func (s *store) save() error {
1151		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1152		for i, e := range s.data.Events {
1153			s.data.EventsJSON[i] = e.toJSON()
1154		}
1155		if err := validateData(s.data); err != nil {
1156			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1157		}
1158		var buf bytes.Buffer
1159		enc := json.NewEncoder(&buf)
1160		enc.SetIndent("", "  ")
1161		if err := enc.Encode(s.data); err != nil {
1162			return fmt.Errorf("编码数据失败: %w", err)
1163		}
1164		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1165			return fmt.Errorf("创建数据目录失败: %w", err)
1166		}
1167		path := filepath.Join(s.dir, dataFileName)
1168		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1169		if err != nil {
1170			return fmt.Errorf("创建临时数据文件失败: %w", err)
1171		}
1172		tmpName := tmp.Name()
1173		abort := func(err error) error {
1174			_ = tmp.Close()
1175			_ = os.Remove(tmpName)
1176			return err
1177		}
1178		if _, err := tmp.Write(buf.Bytes()); err != nil {
1179			abort(nil)
1180			return fmt.Errorf("写入数据失败: %w", err)
1181		}
1182		if err := tmp.Sync(); err != nil {
1183			abort(nil)
1184			return fmt.Errorf("写入数据失败: %w", err)
1185		}
1186		if err := tmp.Close(); err != nil {
1187			_ = os.Remove(tmpName)
1188			return fmt.Errorf("写入数据失败: %w", err)
1189		}
1190		if err := os.Rename(tmpName, path); err != nil {
1191			_ = os.Remove(tmpName)
1192			return fmt.Errorf("保存数据失败: %w", err)
1193		}
1194		return nil
1195	}
1196	
1197	func (s *store) findAsset(id string) *Asset {
1198		for _, a := range s.data.Assets {
1199			if a.ID == id {
1200				return a
1201			}
1202		}
1203		return nil
1204	}
1205	
1206	func (s *store) findTicket(id string) *Ticket {
1207		for _, t := range s.data.Tickets {
1208			if t.ID == id {
1209				return t
1210			}
1211		}
1212		return nil
1213	}
1214	
1215	func (s *store) findRequest(requestID string) *requestBinding {
1216		for i := range s.data.Requests {
1217			if s.data.Requests[i].RequestID == requestID {
1218				return &s.data.Requests[i]
1219			}
1220		}
1221		return nil
1222	}
1223	
1224	func (s *store) openTicketOf(assetID string) *Ticket {
1225		for _, t := range s.data.Tickets {
1226			if t.AssetID == assetID && t.Status == ticketOpen {
1227				return t
1228			}
1229		}
1230		return nil
1231	}
1232	
1233	func (s *store) eventsOf(assetID string) []Event {
1234		out := make([]Event, 0)
1235		for _, e := range s.data.Events {
1236			if e.AssetID == assetID {
1237				out = append(out, e)
1238			}
1239		}
1240		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
1241		return out
1242	}
1243	
1244	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1245	func (s *store) nextEventSeq() (int, error) {
1246		maxSeq := 0
1247		for _, e := range s.data.Events {
1248			if e.Seq > maxSeq {
1249				maxSeq = e.Seq
1250			}
1251		}
1252		if maxSeq == math.MaxInt {
1253			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1254		}
1255		return maxSeq + 1, nil
1256	}
1257	
1258	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
1259	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
1260	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
1261		s.data.Events = append(s.data.Events, Event{
1262			Seq:      seq,
1263			AssetID:  assetID,
1264			TicketID: ticketID,
1265			Kind:     kind,
1266			Content:  content,
1267			From:     from,
1268			To:       to,
1269			Time:     s.now(),
1270		})
1271	}
1272	
1273	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
1274		if s.findAsset(id) != nil {
1275			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
1276		}
1277		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
1278		s.data.Assets = append(s.data.Assets, a)
1279		return a, nil
1280	}
1281	
1282	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1283	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1284	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1285		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1286		// 资产或描述不同 => 拒绝。
1287		if r := s.findRequest(requestID); r != nil {
1288			if r.AssetID != assetID || r.Description != description {
1289				return nil, false, fmt.Errorf(
1290					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1291					errConflict, requestID, r.AssetID)
1292			}
1293			t := s.findTicket(r.TicketID)
1294			if t == nil {
1295				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1296			}
1297			return t, true, nil
1298		}
1299	
1300		asset := s.findAsset(assetID)
1301		if asset == nil {
1302			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1303		}
1304		if asset.Status == statusDeactivated {
1305			// 停用期间拒绝新报修，也不绑定新请求标识；恢复使用后可用同一标识重试。
1306			return nil, false, fmt.Errorf("%w: 资产 %s 已停用，不能报修", errConflict, assetID)
1307		}
1308		if t := s.openTicketOf(assetID); t != nil {
1309			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1310		}
1311		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1312		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1313		seq := s.data.NextTicketSeq
1314		if seq < 1 || seq == math.MaxInt {
1315			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1316		}
1317		eventSeq, err := s.nextEventSeq()
1318		if err != nil {
1319			return nil, false, err
1320		}
1321		t := &Ticket{
1322			ID:          fmt.Sprintf("T%04d", seq),
1323			AssetID:     assetID,
1324			Description: description,
1325			RequestID:   requestID,
1326			Status:      ticketOpen,
1327			CreatedAt:   s.now().Format(time.RFC3339),
1328		}
1329		s.data.NextTicketSeq = seq + 1
1330		s.data.Tickets = append(s.data.Tickets, t)
1331		s.data.Requests = append(s.data.Requests, requestBinding{
1332			RequestID:   requestID,
1333			AssetID:     assetID,
1334			Description: description,
1335			TicketID:    t.ID,
1336		})
1337		asset.Status = statusRepairing
1338		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1339		return t, false, nil
1340	}
1341	
1342	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1343	// 失败路径不修改任何业务数据。
1344	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1345		t := s.findTicket(ticketID)
1346		if t == nil {
1347			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1348		}
1349		if t.Status == ticketCancelled {
1350			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1351		}
1352		if t.Status != ticketOpen {
1353			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1354		}
1355		asset := s.findAsset(t.AssetID)
1356		if asset == nil {
1357			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1358		}
1359		eventSeq, err := s.nextEventSeq()
1360		if err != nil {
1361			return nil, nil, err
1362		}
1363		t.Status = ticketClosed
1364		t.Result = result
1365		t.ClosedAt = s.now().Format(time.RFC3339)
1366		asset.Status = statusAvailable
1367		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1368		return t, asset, nil
1369	}
1370	
1371	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1372	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1373	// 失败路径不修改任何业务数据。
1374	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1375		t := s.findTicket(ticketID)
1376		if t == nil {
1377			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1378		}
1379		if t.Status == ticketCancelled {
1380			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1381		}
1382		if t.Status == ticketClosed {
1383			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1384		}
1385		asset := s.findAsset(t.AssetID)
1386		if asset == nil {
1387			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1388		}
1389		eventSeq, err := s.nextEventSeq()
1390		if err != nil {
1391			return nil, nil, err
1392		}
1393		t.Status = ticketCancelled
1394		t.CancelReason = reason
1395		t.CancelledAt = s.now().Format(time.RFC3339)
1396		asset.Status = statusAvailable
1397		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1398		return t, asset, nil
1399	}
1400	
1401	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1402	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1403	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1404	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1405	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1406	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1407		t := s.findTicket(ticketID)
1408		if t == nil {
1409			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1410		}
1411		if t.Status == ticketClosed {
1412			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1413		}
1414		if t.Status == ticketCancelled {
1415			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1416		}
1417		if assignee == "" {
1418			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1419		}
1420		if note == "" {
1421			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1422		}
1423		if t.Assignee == assignee {
1424			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1425				errConflict, ticketID, assignee)
1426		}
1427		eventSeq, err := s.nextEventSeq()
1428		if err != nil {
1429			return nil, err
1430		}
1431		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1432		t.Assignee = assignee
1433		t.AssignedAt = s.now().Format(time.RFC3339)
1434		t.AssignNote = note
1435		return t, nil
1436	}
1437

