1	package main
2	
3	import (
4		"fmt"
5		"math"
6		"math/big"
7		"sort"
8	)
9	
10	// 维修工单备件领用与退回台账。
11	//
12	// 领用：仅未关闭工单可领用，输入工单编号、非空备件编号、正整数数量（工单用量）
13	// 与非空说明；每次成功生成同目录唯一且不复用的领用编号（P 加补零序号），并追加
14	// 一条领用履历。同备件多次领用各自独立，领用编号用于定位记录，不用报修请求标识
15	// 代替。
16	//
17	// 退回：输入领用编号、正整数数量与非空理由，作用于该笔领用所属的工单；允许多次
18	// 部分退回，累计不得超过该笔原数量，也不能冲减另一笔。成功时更新累计退回并追加
19	// 一条退回履历，净量 = 原数量 - 累计退回。
20	//
21	// 工单关闭或取消后保留领用记录与净量，不自动清零；终结后拒绝领用与退回，
22	// 旧单的记录不影响新工单。领用、退回各为一次原子保存：校验、数量或编号容量
23	// 不足、读写失败时保留原文件字节，不留下部分记录、不消耗编号，恢复后可重试。
24	
25	// findPart 按领用编号查找领用记录，不存在时返回 nil。
26	func (s *store) findPart(id string) *PartWithdrawal {
27		for _, p := range s.data.Parts {
28			if p.ID == id {
29				return p
30			}
31		}
32		return nil
33	}
34	
35	// withdrawSeqs 返回每笔领用编号对应的领用履历全库序号。领用编号只用于定位
36	// 记录：各笔领用的先后由该笔唯一领用履历的序号决定，与记录数组位置、编号
37	// 大小及履历时间无关（有效台账允许数组乱序、序号间隔、时间不递增以及编号
38	// 大小与领用先后不一致）。
39	func (s *store) withdrawSeqs() map[string]int {
40		seqs := make(map[string]int, len(s.data.Parts))
41		for _, e := range s.data.Events {
42			if e.Kind == eventPartWithdraw {
43				seqs[e.WithdrawalID] = e.Seq
44			}
45		}
46		return seqs
47	}
48	
49	// partsOf 按领用先后返回工单的全部领用记录：顺序由每笔唯一领用履历的全库
50	// 序号决定，不使用数组位置或编号大小。
51	func (s *store) partsOf(ticketID string) []*PartWithdrawal {
52		seqs := s.withdrawSeqs()
53		out := make([]*PartWithdrawal, 0)
54		for _, p := range s.data.Parts {
55			if p.TicketID == ticketID {
56				out = append(out, p)
57			}
58		}
59		sort.SliceStable(out, func(i, j int) bool { return seqs[out[i].ID] < seqs[out[j].ID] })
60		return out
61	}
62	
63	// partNetRow 为按备件编号汇总的一行净量。Net 为精确十进制整数：同备件多笔
64	// 净量之和可能超出单笔数量范围，汇总不得回绕或截断，也不因此拒绝合法台账。
65	type partNetRow struct {
66		PartID string
67		Net    *big.Int
68	}
69	
70	// partNetSummary 按备件编号字典序汇总工单各笔领用的净量；全部退回的备件
71	// 净量为零仍显示。
72	func (s *store) partNetSummary(ticketID string) []partNetRow {
73		nets := map[string]*big.Int{}
74		for _, p := range s.partsOf(ticketID) {
75			acc := nets[p.PartID]
76			if acc == nil {
77				acc = new(big.Int)
78				nets[p.PartID] = acc
79			}
80			acc.Add(acc, big.NewInt(int64(p.Quantity-p.Returned)))
81		}
82		rows := make([]partNetRow, 0, len(nets))
83		for partID, net := range nets {
84			rows = append(rows, partNetRow{PartID: partID, Net: net})
85		}
86		sort.Slice(rows, func(i, j int) bool { return rows[i].PartID < rows[j].PartID })
87		return rows
88	}
89	
90	// appendPartEvent 以给定序号追加备件履历（领用或退回）。备件履历属于领用记录
91	// 所在的工单，from/to 与保养字段恒为空；content 为领用说明或退回理由。
92	func (s *store) appendPartEvent(seq int, p *PartWithdrawal, kind string, quantity int, content string) {
93		s.data.Events = append(s.data.Events, Event{
94			Seq:          seq,
95			AssetID:      p.AssetID,
96			TicketID:     p.TicketID,
97			Kind:         kind,
98			Content:      content,
99			PartID:       p.PartID,
100			Quantity:     quantity,
101			WithdrawalID: p.ID,
102			Time:         s.now(),
103		})
104	}
105	
106	// withdrawPart 为未关闭工单领用备件：生成同目录唯一且不复用的领用编号，
107	// 追加一条领用履历。失败路径不修改任何业务数据，也不消耗领用编号。
108	func (s *store) withdrawPart(ticketID, partID string, quantity int, note string) (*PartWithdrawal, error) {
109		t := s.findTicket(ticketID)
110		if t == nil {
111			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
112		}
113		if t.Status == ticketClosed {
114			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能领用备件", errConflict, ticketID)
115		}
116		if t.Status == ticketCancelled {
117			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能领用备件", errConflict, ticketID)
118		}
119		if partID == "" {
120			return nil, fmt.Errorf("%w: 备件编号不能为空", errConflict)
121		}
122		if note == "" {
123			return nil, fmt.Errorf("%w: 领用说明不能为空", errConflict)
124		}
125		if quantity < 1 {
126			return nil, fmt.Errorf("%w: 领用数量须为正整数", errConflict)
127		}
128		// 先确认领用编号与履历计数器都能推进，再修改任何业务数据：
129		// 编号耗尽时拒绝领用，不消耗编号，也不产生履历。
130		seq := s.data.NextPartSeq
131		if seq < 1 || seq == math.MaxInt {
132			return nil, fmt.Errorf("%w: 领用编号计数器已耗尽，无法分配新领用编号", errConflict)
133		}
134		eventSeq, err := s.nextEventSeq()
135		if err != nil {
136			return nil, err
137		}
138		p := &PartWithdrawal{
139			ID:       fmt.Sprintf("P%04d", seq),
140			TicketID: t.ID,
141			AssetID:  t.AssetID,
142			PartID:   partID,
143			Quantity: quantity,
144			Note:     note,
145		}
146		s.data.NextPartSeq = seq + 1
147		s.data.Parts = append(s.data.Parts, p)
148		s.appendPartEvent(eventSeq, p, eventPartWithdraw, quantity, note)
149		return p, nil
150	}
151	
152	// returnPart 按领用编号退回备件：作用于该笔领用所属的工单，允许多次部分退回，
153	// 累计不得超过该笔原数量，也不能冲减另一笔。成功时更新累计退回并追加一条退回
154	// 履历。失败路径不修改任何业务数据。
155	func (s *store) returnPart(withdrawalID string, quantity int, reason string) (*PartWithdrawal, *Ticket, error) {
156		p := s.findPart(withdrawalID)
157		if p == nil {
158			return nil, nil, fmt.Errorf("%w: 未知领用编号 %q", errNotFound, withdrawalID)
159		}
160		t := s.findTicket(p.TicketID)
161		if t == nil {
162			return nil, nil, fmt.Errorf("数据内部错误：领用记录 %s 引用的工单不存在", withdrawalID)
163		}
164		if t.Status == ticketClosed {
165			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能退回备件", errConflict, t.ID)
166		}
167		if t.Status == ticketCancelled {
168			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能退回备件", errConflict, t.ID)
169		}
170		if reason == "" {
171			return nil, nil, fmt.Errorf("%w: 退回理由不能为空", errConflict)
172		}
173		if quantity < 1 {
174			return nil, nil, fmt.Errorf("%w: 退回数量须为正整数", errConflict)
175		}
176		// 剩余可退数量 = 原数量 - 累计退回（两者均在 [0, 原数量] 内，减法不会溢出）；
177		// 退回数量超过剩余即拒绝。不做 Returned+quantity 的加法比较：大数量相加
178		// 可能整数溢出回绕成负数，从而错误接受超额退回。
179		if quantity > p.Quantity-p.Returned {
180			return nil, nil, fmt.Errorf(
181				"%w: 备件数量问题：领用记录 %s 原数量 %d，已退回 %d，再退 %d 将超过原数量",
182				errConflict, p.ID, p.Quantity, p.Returned, quantity)
183		}
184		eventSeq, err := s.nextEventSeq()
185		if err != nil {
186			return nil, nil, err
187		}
188		p.Returned += quantity
189		s.appendPartEvent(eventSeq, p, eventPartReturn, quantity, reason)
190		return p, t, nil
191	}
