11	)
12	
13	// baseLedger 是一份合法但编号与履历序号都有间隔的旧格式台账：
14	// 工单 T0001 未关闭，下一工单序号 5，履历序号 3。
15	const baseLedger = `{
16	  "version": 1,
17	  "assets": [{"id":"EQ-1","name":"打印机","location":"一楼","status":"维修中"}],
18	  "tickets": [{"id":"T0001","asset_id":"EQ-1","description":"卡纸","request_id":"req-1","status":"未关闭","created_at":"2026-10-01T08:00:00Z"}],
19	  "events": [{"seq":3,"asset_id":"EQ-1","ticket_id":"T0001","kind":"报修","content":"卡纸","time":"2026-10-01T08:00:00Z"}],
20	  "requests": [{"request_id":"req-1","asset_id":"EQ-1","description":"卡纸","ticket_id":"T0001"}],
21	  "next_ticket_seq": 5
22	}`
23	
24	// writeLedger 把 baseLedger 经 mutate 修改后写入数据目录，返回写入的字节。
25	func writeLedger(t *testing.T, dir string, mutate func(m map[string]any)) []byte {
26		t.Helper()
27		var m map[string]any
28		if err := json.Unmarshal([]byte(baseLedger), &m); err != nil {
29			t.Fatal(err)
30		}
31		if mutate != nil {
32			mutate(m)
33		}
34		raw, err := json.Marshal(m)
35		if err != nil {
36			t.Fatal(err)
37		}
38		if err := os.WriteFile(filepath.Join(dir, dataFileName), raw, 0o644); err != nil {
39			t.Fatal(err)
40		}
41		return raw
42	}
43	
44	func openTicketJSON(id, req string) map[string]any {
45		return map[string]any{
46			"id": id, "asset_id": "EQ-1", "description": "卡纸",
47			"request_id": req, "status": "未关闭", "created_at": "2026-10-01T09:00:00Z",
48		}
49	}
50	
51	func eventJSONMap(seq int, ticketID, kind, content string) map[string]any {
52		return map[string]any{
53			"seq": seq, "asset_id": "EQ-1", "ticket_id": ticketID,
54			"kind": kind, "content": content, "time": "2026-10-01T10:00:00Z",
55		}
