57	
58	func appendTo(m map[string]any, key string, v any) {
59		m[key] = append(m[key].([]any), v)
60	}
61	
62	// cancelLedger 把 baseLedger 中的 T0001 改为合法的已取消终态（含取消履历、资产可用）。
63	func cancelLedger(m map[string]any) {
