514	// 含已取消工单的有效旧台账无需转换即可加载：去重重放返回已取消状态，
515	// 新报修从计数器延续编号，取消后资产可再次报修，重启后状态保持。
516	func TestValidCancelledLegacyLedger(t *testing.T) {
517		dir := t.TempDir()
518		writeLedger(t, dir, cancelLedger)
519	
520		s, err := openStore(dir)
521		if err != nil {
522			t.Fatalf("含已取消工单的有效旧库应能加载: %v", err)
523		}
524		// 重放旧请求：返回原工单的已取消状态，不产生工单或履历，不重新占用资产。
525		old, replay, err := s.report("EQ-1", "卡纸", "req-1")
526		if err != nil || !replay || old.ID != "T0001" || old.Status != ticketCancelled {
527			t.Fatalf("重放应返回已取消的 T0001: %v replay=%v err=%v", old, replay, err)
528		}
529		if len(s.data.Tickets) != 1 || len(s.data.Events) != 2 {
530			t.Fatal("重放不应产生工单或履历")
531		}
532		if got := s.findAsset("EQ-1").Status; got != statusAvailable {
533			t.Fatalf("重放不应重新占用资产，状态 = %q", got)
534		}
535		// 新报修从计数器 5 延续编号。
536		tk, replay, err := s.report("EQ-1", "无法开机", "req-2")
537		if err != nil || replay || tk.ID != "T0005" {
538			t.Fatalf("新报修应开出 T0005: %v replay=%v err=%v", tk, replay, err)
539		}
540		// 旧请求重放不影响新单。
541		old, replay, err = s.report("EQ-1", "卡纸", "req-1")
542		if err != nil || !replay || old.Status != ticketCancelled {
543			t.Fatalf("已有新单时重放仍返回已取消的 T0001: %v replay=%v err=%v", old, replay, err)
544		}
545		if got := s.openTicketOf("EQ-1"); got == nil || got.ID != "T0005" {
546			t.Fatalf("新工单 T0005 应仍为未关闭，得到 %v", got)
547		}
548		// 取消新工单并保存重开：取消状态、理由、履历与去重结果保持。
549		if _, _, err := s.cancelTicket("T0005", "用户自行解决"); err != nil {
550			t.Fatal(err)
551		}
552		if err := s.save(); err != nil {
553			t.Fatal(err)
554		}
555		s2, err := openStore(dir)
556		if err != nil {
557			t.Fatal(err)
558		}
559		got := s2.findTicket("T0005")
560		if got.Status != ticketCancelled || got.CancelReason != "用户自行解决" || got.CancelledAt == "" {
561			t.Fatalf("重开后 T0005 取消状态未保持: %+v", got)
562		}
563		if got := s2.findTicket("T0001"); got.Status != ticketCancelled ||
564			got.CancelReason != "误报，设备实际正常" {
565			t.Fatalf("重开后 T0001 取消状态未保持: %+v", got)
566		}
567		events := s2.eventsOf("EQ-1")
568		if len(events) != 4 || events[0].Kind != eventReport || events[1].Kind != eventCancel ||
569			events[2].Kind != eventReport || events[3].Kind != eventCancel {
570			t.Fatalf("重开后履历不对: %+v", events)
571		}
572		if events[1].Content != "误报，设备实际正常" || events[3].Content != "用户自行解决" {
573			t.Fatalf("取消履历内容应为取消理由: %+v", events)
574		}
575		// 同标识搭配不同资产或描述仍被拒绝，取消不释放旧请求标识。
576		if _, _, err := s2.report("EQ-1", "别的故障", "req-1"); err == nil {
577			t.Fatal("同标识不同描述应被拒绝")
578		}
579	}
