// 序号为准，不使用数组位置或履历时间。
func sortedLocationEvents(events []Event) []Event {
	out := make([]Event, 0)
	for _, e := range events {
		if e.Kind == eventRelocate {
			out = append(out, e)
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
