// 每张工单恰有一条报修履历；调用前已完成校验时第二个返回值恒为 true。
func (s *store) reportEventSeq(ticketID string) (int, bool) {
	for _, e := range s.data.Events {
		if e.Kind == eventReport && e.TicketID == ticketID {
			return e.Seq, true
		}
	}
	return 0, false
}

